CREATE TABLE project_execution_consumptions(
 project_id TEXT NOT NULL, claim_id TEXT NOT NULL, registration_digest TEXT NOT NULL,
 grant BLOB NOT NULL, consumed_at_ms INTEGER NOT NULL,
 PRIMARY KEY(project_id,claim_id), UNIQUE(project_id,registration_digest),
 FOREIGN KEY(project_id,claim_id) REFERENCES result_reservations(project_id,claim_id));
CREATE TABLE project_holds(
 project_id TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('driver_entry','preparation','lease','reservation','orchestration','open_binding','result_custody')),
 identity TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('held','releasing','released')),
 generation INTEGER NOT NULL DEFAULT 1 CHECK(generation>=1),
 instance TEXT,lease_case TEXT CHECK(lease_case IN ('unarmed','armed','closing_denied','admitted_unbound')),
 taken_at_ms INTEGER NOT NULL,due_at_ms INTEGER,next_check_ms INTEGER NOT NULL DEFAULT 0,
 released_at_ms INTEGER,release_kind TEXT,request_id TEXT,request_digest TEXT,receipt TEXT,evidence TEXT,
 CHECK((kind='lease')=(lease_case IS NOT NULL)),
 CHECK((kind IN ('driver_entry','preparation'))=(instance IS NOT NULL)),
 CHECK(state='released' OR released_at_ms IS NULL),
 CHECK(state<>'released' OR release_kind IS NOT NULL),
 CHECK(release_kind IS NULL OR (kind='lease' AND release_kind IN ('withdrawn_unsent','denied','fenced','bound','lost_unbound')) OR (kind='reservation' AND release_kind IN ('completed','lost','crashed','released_unacknowledged')) OR (kind='driver_entry' AND release_kind IN ('retired','handed_over','service_stopped')) OR (kind='preparation' AND release_kind IN ('retired','submit_refused','never_launch_local','service_stopped')) OR (kind='orchestration' AND release_kind IN ('closed','interrupted_unattended')) OR (kind='open_binding' AND release_kind IN ('withdrawn','claimed','fenced','account_final')) OR (kind='result_custody' AND release_kind IN ('lost_with_reservation','retention','orchestration_closed'))),
 PRIMARY KEY(project_id,kind,identity),
 FOREIGN KEY(project_id) REFERENCES history_identity(project_id));
